<script setup>
import { computed, ref, watch } from 'vue'
import { SHOPPING_APP_PAGE_EVENTS, SHOPPING_APP_PAGE_PROPS, localizeAppPage } from './shopping-app-page-contract'

const props = defineProps(SHOPPING_APP_PAGE_PROPS)
const emit = defineEmits(SHOPPING_APP_PAGE_EVENTS)
const l = (zh, en) => localizeAppPage(props.languageBase, zh, en)
const searchChanged = (event) => emit('update:searchQuery', event.target.value)
const quantity = ref(1)
const activeTab = ref('overview')
const tabs = computed(() => [
  { key: 'overview', label: l('商品介绍', 'Overview') },
  { key: 'details', label: l('商品信息', 'Product info') },
  { key: 'reviews', label: l('评价', 'Reviews') },
  { key: 'delivery', label: l('配送与退换', 'Delivery & returns') },
])
watch(() => props.product?.id, () => { quantity.value = 1; activeTab.value = 'overview' })
</script>

<template>
  <main class="ikea-pages" :data-page="pageKey" data-testid="shopping-store-specific-page">
    <header class="ik-pagebar">
      <button type="button" :aria-label="l('返回','Back')" @click="emit('back')"><i class="fas fa-arrow-left"></i></button>
      <strong><span>IKEA</span> KOREA</strong>
      <div><button type="button" @click="emit('open-orders')">{{ l('订单','Orders') }}</button><button type="button" data-testid="shopping-page-cart" :aria-label="l('购物清单','Shopping list')" @click="emit('open-cart')"><i class="fas fa-bag-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div>
    </header>

    <template v-if="pageKey === 'category'">
      <section class="ik-category-intro">
        <div><p>{{ l('按空间寻找商品','SHOP BY SPACE') }}</p><h1>{{ category?.label || l('家居商品','Home products') }}</h1><span>{{ l('先筛选需要解决的空间，再比较单品。','Choose the space first, then compare individual products.') }}</span></div>
        <div class="ik-room-map" aria-hidden="true"><span class="wall"></span><span class="sofa"></span><span class="shelf"></span><span class="rug"></span><b>ROOM VIEW</b></div>
      </section>

      <form class="ik-catalog-search" @submit.prevent="emit('submit-search')"><i class="fas fa-magnifying-glass"></i><input type="search" :value="searchQuery" :placeholder="l('搜索商品名称或用途','Search by product or use')" @input="searchChanged" /><button type="submit">{{ l('搜索','Search') }}</button></form>
      <nav class="ik-category-tabs" :aria-label="l('商品分类','Product categories')"><button v-for="item in categories" :key="item.key" type="button" :class="{ active: item.key === category?.key }" @click="emit('select-category', item.key)"><i :class="item.icon"></i><span>{{ item.label }}</span><small>{{ item.count }}</small></button></nav>

      <section class="ik-catalog-heading"><div><p>{{ l('当前分类','CURRENT CATEGORY') }}</p><h2>{{ l('比较适合这个空间的单品','Compare objects for this space') }}</h2></div><span>{{ totalCount }} {{ l('件商品','items') }}</span></section>
      <section class="ik-catalog-grid">
        <article v-for="product in products" :key="product.id" class="shopping-product-card" :data-testid="`shopping-product-${product.id}`">
          <button type="button" class="ik-catalog-media" @click="emit('open-product', product.id)"><img v-if="productImageUrl(product)" :src="productImageUrl(product)" :alt="productDisplayTitle(product)" /><span v-else><i :class="productCategoryIcon(product)"></i></span></button>
          <button type="button" class="ik-card-favorite" :class="{ active: isProductFavorite(product.id) }" :aria-label="l('切换收藏','Toggle favorite')" @click="emit('toggle-favorite', product.id)"><i class="fas fa-heart"></i></button>
          <div><button type="button" @click="emit('open-product', product.id)"><h3>{{ productDisplayTitle(product) }}</h3></button><p>{{ productDisplayDescription(product) }}</p><span>{{ stockStatusLabel(product.stockStatus) }}</span><footer><strong>{{ formatPrice(product) }}</strong><button type="button" :disabled="product.stockStatus === 'sold_out'" @click="emit('add-to-cart', product.id)">{{ l('加入清单','Add') }}</button></footer></div>
        </article>
      </section>
      <nav v-if="pageCount > 1" class="ik-pagination" data-testid="shopping-pagination"><button type="button" :disabled="page <= 1" @click="emit('change-page', page - 1)"><i class="fas fa-arrow-left"></i>{{ l('上一页','Previous') }}</button><span>{{ page }} / {{ pageCount }}</span><button type="button" :disabled="page >= pageCount" @click="emit('change-page', page + 1)">{{ l('下一页','Next') }}<i class="fas fa-arrow-right"></i></button></nav>
    </template>

    <template v-else-if="product">
      <section class="ik-pdp-buybox">
        <div class="ik-pdp-media"><img v-if="productImageUrl(product)" :src="productImageUrl(product)" :alt="productDisplayTitle(product)" /><div v-else class="ik-object-stage"><span class="floor"></span><span class="object"><i :class="productCategoryIcon(product)"></i></span><b>{{ l('空间展示','ROOM VIEW') }}</b></div></div>
        <aside>
          <p>{{ serviceLabel }}</p><h1>{{ productDisplayTitle(product) }}</h1><span>{{ productDisplayDescription(product) }}</span><strong>{{ formatPrice(product) }}</strong>
          <dl><div><dt>{{ l('库存状态','Availability') }}</dt><dd>{{ stockStatusLabel(product.stockStatus) }}</dd></div><div v-if="product.assetEligible"><dt>{{ l('购买后','After purchase') }}</dt><dd>{{ l('可加入资产','Asset eligible') }}</dd></div><div v-if="product.giftable"><dt>{{ l('礼赠','Gift') }}</dt><dd>{{ l('支持礼赠下单','Gift option available') }}</dd></div></dl>
          <div class="ik-pdp-actions"><div><button type="button" :aria-label="l('减少数量','Decrease quantity')" :disabled="quantity <= 1" @click="quantity--">−</button><span>{{ quantity }}</span><button type="button" :aria-label="l('增加数量','Increase quantity')" @click="quantity++">+</button></div><button type="button" :class="{ active: isProductFavorite(product.id) }" :aria-label="l('切换收藏','Toggle favorite')" @click="emit('toggle-favorite', product.id)"><i class="fas fa-heart"></i></button></div>
          <button type="button" class="ik-add-primary" data-testid="shopping-product-add" :disabled="product.stockStatus === 'sold_out'" @click="emit('add-to-cart', product.id, quantity)">{{ l('加入购物清单','Add to shopping list') }}</button>
        </aside>
      </section>

      <nav class="ik-pdp-tabs" role="tablist" :aria-label="l('商品详情','Product details')"><button v-for="tab in tabs" :key="tab.key" type="button" role="tab" :aria-selected="activeTab === tab.key" :class="{ active: activeTab === tab.key }" @click="activeTab = tab.key">{{ tab.label }}</button></nav>
      <section class="ik-pdp-panel">
        <template v-if="activeTab === 'overview'"><div class="ik-overview-copy"><p>DESIGNED FOR EVERYDAY LIFE</p><h2>{{ l('把单品放回真实的生活任务中判断','Judge the object in the context of daily life') }}</h2><span>{{ productDisplayDescription(product) }}</span></div><div class="ik-overview-scene"><span class="window"></span><span class="shelf"></span><span class="chair"></span><i :class="productCategoryIcon(product)"></i></div></template>
        <template v-else-if="activeTab === 'details'"><div class="ik-info-list"><article><i class="fas fa-circle-info"></i><div><h2>{{ l('商品说明','Product description') }}</h2><p>{{ productDisplayDescription(product) }}</p></div></article><article><i class="fas fa-box-open"></i><div><h2>{{ l('包装与组装信息','Packaging and assembly') }}</h2><p>{{ l('这件商品暂无更多包装或组装说明；可用服务以结算页为准。','No additional packaging or assembly details are available; review eligible services at checkout.') }}</p></div></article></div></template>
        <template v-else-if="activeTab === 'reviews'"><div class="ik-review-empty"><i class="fas fa-message"></i><h2>{{ l('还没有商品评价','No reviews yet') }}</h2><p>{{ l('订单完成后，真实购买记录可在这里提交评分与使用照片。','Verified buyers can add ratings and room photos after completion.') }}</p></div></template>
        <template v-else><div class="ik-info-list"><article><i class="fas fa-truck"></i><div><h2>{{ l('配送','Delivery') }}</h2><p>{{ l('可用方式与费用在结算确认，并记录到订单中。','Available methods and fees are confirmed at checkout and recorded with the order.') }}</p></div></article><article><i class="fas fa-rotate-left"></i><div><h2>{{ l('退换与售后','Returns and support') }}</h2><p>{{ l('请从已创建的订单进入售后与物流记录。','Open the recorded order for returns, support, and delivery updates.') }}</p></div></article></div></template>
      </section>

      <section class="ik-related-section"><div><p>{{ l('搭配这个空间','COMPLETE THE ROOM') }}</p><h2>{{ l('同一分类的其他选择','More options in this category') }}</h2></div><div><button v-for="item in relatedProducts.slice(0, 4)" :key="item.id" type="button" @click="emit('open-product', item.id)"><span><img v-if="productImageUrl(item)" :src="productImageUrl(item)" :alt="productDisplayTitle(item)" /><i v-else :class="productCategoryIcon(item)"></i></span><strong>{{ productDisplayTitle(item) }}</strong><small>{{ formatPrice(item) }}</small></button></div></section>
    </template>
  </main>
</template>

